class AsyncOrgTaskResource:
    def __init__(self, http: HttpClient):
        self._http = http

    async def list(
        self,
        org: str,
        *,
        status: str | None = None,
        owner_user: str | None = None,
        owner_agent: str | None = None,
        priority: int | None = None,
        tag: str | None = None,
        parent: str | None = None,
        source_scope: str | None = None,
        source_type: str | None = None,
        source_id: str | None = None,
        epic: str | None = None,
        search: str | None = None,
        sort: str | None = None,
        order: str | None = None,
        due_before: str | None = None,
        due_after: str | None = None,
        overdue: bool | None = None,
        ready: bool | None = None,
        attention: bool | None = None,
        limit: int | None = None,
        after_cursor: str | None = None,
    ) -> OrgTaskListResponse:
        """
        List an organization's tasks
        Returns org-owned tasks for the specified organization: rows with the org
        tenant and no narrower user/team/agent scope. Explicitly personal, team, or
        agent tasks are excluded here; list those via the user/team collections or
        fetch them directly when authorized.
        Every organization member may list. App-scoped developer and
        server-to-server callers supply the org in the route.

        Args:
            org: Organization ID (`org_...`) whose org-owned tasks should be returned.
            status: Filter tasks by status. One of `"open"`, `"in_progress"`, `"in_review"`, or `"done"`. Omit to return tasks in all statuses.
            owner_user: Filter tasks assigned to a specific user. Provide the user's public ID (`usr_...`).
            owner_agent: Filter tasks assigned to a specific agent. Provide the agent's public ID (`agi_...`).
            priority: Filter tasks by priority, from 0 (highest) to 4 (lowest).
            tag: Return only tasks carrying this tag (matched against the canonical lowercase form).
            parent: Return only subtasks of the given task (`tsk_...`), or pass `none` to return only top-level tasks.
            source_scope: Return only tasks whose source matches this container. Must be supplied with `source_type` and `source_id`.
            source_type: Return only tasks whose source matches this object kind. Must be supplied with the other source filters.
            source_id: Return only tasks whose source matches this object identity. Must be supplied with the other source filters.
            epic: Return only tasks with this exact epic label.
            search: Restrict results to tasks whose name or description contains this string.
            sort: Sort key. One of `"created"` (default most recently created first), `"due_date"` (soonest due first; tasks without a due date always sort last), or `"priority"` (most urgent first). Ties break by most recently created.
            order: Sort direction, `"asc"` or `"desc"`. Defaults to `"desc"` for `created` and `"asc"` for `due_date` and `priority`.
            due_before: Return only tasks with a due date strictly before this ISO 8601 datetime (`2026-08-01T00:00:00Z`) or date (`2026-08-01`, meaning midnight UTC). Tasks without a due date are excluded.
            due_after: Return only tasks with a due date strictly after this ISO 8601 datetime or date. Tasks without a due date are excluded.
            overdue: When `true`, return only overdue tasks: a due date before the current UTC day and a status other than `"done"`. A task due today is not overdue.
            ready: When true, return only open tasks with no unfinished blockers and no active session lease. This is a projection snapshot; claim a lease before starting work.
            attention: When true, return paused, failed, or in-progress tasks with no lease or a past lease expiry.
            limit: Maximum number of tasks to return. Capped at 100.
            after_cursor: Opaque cursor returned by the previous page.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        if status is not None:
            query["status"] = status
        if owner_user is not None:
            query["owner_user"] = owner_user
        if owner_agent is not None:
            query["owner_agent"] = owner_agent
        if priority is not None:
            query["priority"] = priority
        if tag is not None:
            query["tag"] = tag
        if parent is not None:
            query["parent"] = parent
        if source_scope is not None:
            query["source_scope"] = source_scope
        if source_type is not None:
            query["source_type"] = source_type
        if source_id is not None:
            query["source_id"] = source_id
        if epic is not None:
            query["epic"] = epic
        if search is not None:
            query["search"] = search
        if sort is not None:
            query["sort"] = sort
        if order is not None:
            query["order"] = order
        if due_before is not None:
            query["due_before"] = due_before
        if due_after is not None:
            query["due_after"] = due_after
        if overdue is not None:
            query["overdue"] = overdue
        if ready is not None:
            query["ready"] = ready
        if attention is not None:
            query["attention"] = attention
        if limit is not None:
            query["limit"] = limit
        if after_cursor is not None:
            query["after_cursor"] = after_cursor
        return await self._http.request(
            f"/api/v1/orgs/{org}/tasks",
            query=query,
            response_type=OrgTaskListResponse,
        )

    async def create(self, org: str, input: OrgTaskCreateInput) -> Task:
        """
        Create a task for an organization
        Creates a new org-owned task (org tenant, no narrower user/team/agent
        scope) and returns the full task object. User-authenticated calls are
        attributed to the authenticated user or agent. App-scoped developer and
        server-to-server callers must provide an explicit `user` or `agent` actor
        for the organization. Every referenced principal is validated against the
        app and organization before creation.

        Args:
            org: Organization ID (`org_...`) whose org-owned tasks should be returned.
            input: Request body.
            input.agent: Explicit acting agent (`agi_...`) for a developer or server-to-server call. Mutually exclusive with an acting `user`; the agent must belong to the organization.
            input.task: Attributes for the task to create. `name` is required; all other fields are optional.
            input.user: Explicit acting user (`usr_...`) for a developer or server-to-server call. Mutually exclusive with an acting `agent`.

        Returns:
            The newly created task.
        """
        return await self._http.request(
            f"/api/v1/orgs/{org}/tasks",
            method="POST",
            body=input,
            response_type=Task,
        )

    async def blocker_cycles(
        self, org: str, *, limit: int | None = None, after_cursor: str | None = None
    ) -> OrgTaskBlockerCyclesResponse:
        """
        List task blocker cycles for an organization
        Runs an on-demand diagnostic over unfinished org-owned tasks for the
        specified organization and returns a forward cursor-paginated page of
        complete cyclic blocker components. Detection is bounded to owners with at
        most 100 unfinished tasks. This endpoint is read-only: cycles do not prevent
        task updates, lease acquisition, or completion.

        Args:
            org: Organization ID (`org_...`) whose org-owned tasks should be returned.
            limit: Maximum cycle components to return. Defaults to 50; maximum is 100.
            after_cursor: Opaque cursor returned by the preceding page.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        if limit is not None:
            query["limit"] = limit
        if after_cursor is not None:
            query["after_cursor"] = after_cursor
        return await self._http.request(
            f"/api/v1/orgs/{org}/tasks/blocker_cycles",
            query=query,
            response_type=OrgTaskBlockerCyclesResponse,
        )

    async def by_source(self, org: str, input: OrgTaskBySourceInput) -> TaskEnsureResult:
        """
        Find or create a task by source
        Atomically creates one task per owner, tenant and source. Retries return the current task without updating it. Historical tasks created through ordinary create are not adopted.

        Args:
            org: Organization ID (`org_...`) whose org-owned tasks should be returned.
            input: Request body.
            input.agent: Explicit acting agent for privileged callers.
            input.description: Initial task description.
            input.epic: Initial epic grouping.
            input.name: Initial task name.
            input.source_id: Source identity, for example owner/repo#123.
            input.source_scope: Source scope, for example github.
            input.source_type: Source type, for example pull_request.
            input.status: Initial task status.
            input.team: Team owner.
            input.user: User owner, or explicit acting user on a team route.

        Returns:
            The task and whether this request created it.
        """
        return await self._http.request(
            f"/api/v1/orgs/{org}/tasks/by-source",
            method="PUT",
            body=input,
            response_type=TaskEnsureResult,
        )

    async def metrics(self, org: str, *, days: int | None = None) -> OrgTaskMetricsResponse:
        """
        Get task activity metrics for an organization
        Returns task activity metrics scoped to org-owned tasks (org tenant, no
        narrower user/team/agent scope). `open` counts currently open or
        in-progress org tasks, `created` counts tasks inserted in the UTC-day
        window, and `completed` counts tasks whose `closed_at` falls in that window
        while still in a closed status. Hard-deleted tasks are absent from the
        projection and therefore omitted. The daily series is zero-filled across
        the requested window and includes reconstructed end-of-day `open` stock.
        Any organization member may read this count-only summary. Requests from
        callers without org access return 404 so organization existence is not
        disclosed.

        Args:
            org: Organization ID (`org_...`) whose org-owned tasks should be returned.
            days: UTC-day window. One of 7, 30, 90, or 365; defaults to 30.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        if days is not None:
            query["days"] = days
        return await self._http.request(
            f"/api/v1/orgs/{org}/tasks/metrics",
            query=query,
            response_type=OrgTaskMetricsResponse,
        )

    async def ready(
        self,
        org: str,
        *,
        explain: bool | None = None,
        assigned_to_me: bool | None = None,
        source_scope: str | None = None,
        source_type: str | None = None,
        source_id: str | None = None,
        epic: str | None = None,
        limit: int | None = None,
        after_cursor: str | None = None,
    ) -> OrgTaskReadyResponse:
        """
        List an organization's ready tasks
        Returns open org-owned tasks with no unfinished blockers and no active
        session lease. Readiness is calculated by the server from the current task
        projection. It is a snapshot, not a reservation; claim a task lease before
        starting work.
        Results are ordered by priority (0, the most urgent, first), then oldest
        first, so the first page is always the most urgent ready work.
        Pass `explain=true` to include every open task with a stable readiness reason.

        Args:
            org: Organization ID (`org_...`) whose org-owned tasks should be returned.
            explain: Include blocked and actively leased open tasks with exclusion reasons.
            assigned_to_me: Only include tasks assigned to the authenticated user.
            source_scope: Only include tasks whose source matches this container. Must be supplied with `source_type` and `source_id`.
            source_type: Only include tasks whose source matches this object kind.
            source_id: Only include tasks whose source matches this object identity.
            epic: Only include tasks with this exact epic label.
            limit: Maximum number of readiness entries to return. Capped at 100.
            after_cursor: Opaque cursor returned by the previous page.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        if explain is not None:
            query["explain"] = explain
        if assigned_to_me is not None:
            query["assigned_to_me"] = assigned_to_me
        if source_scope is not None:
            query["source_scope"] = source_scope
        if source_type is not None:
            query["source_type"] = source_type
        if source_id is not None:
            query["source_id"] = source_id
        if epic is not None:
            query["epic"] = epic
        if limit is not None:
            query["limit"] = limit
        if after_cursor is not None:
            query["after_cursor"] = after_cursor
        return await self._http.request(
            f"/api/v1/orgs/{org}/tasks/ready",
            query=query,
            response_type=OrgTaskReadyResponse,
        )

